WITH wave5_payload(document) AS (
  VALUES ('{"schema":"forensic-analysis-v1","as_of":"2026-07-29","generated_migration":"0052_exchange_wave5_forensic_analysis.sql","scope_note":"Wave 5 closes the explicit 25-DEX publication target by upgrading eight existing DEX rows: three operating venues with successful or middling outcomes and five failed products. Each analysis distinguishes observed events from causal inference. Residual TVL in deprecated contracts is not treated as an operating exchange, token survival is not treated as product success, and an active successor or ecosystem is not conflated with the failed product in scope.","cases":[{"table":"successful_exchanges","kind":"dex","slug":"raydium","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"successful","summary":"Raydium remains an operating Solana liquidity venue spanning constant-product and concentrated-liquidity pools, token launches, farms, and a perpetuals interface. DefiLlama''s cited adapter reported about $2.44 billion of 30-day spot DEX volume and $812.8 million of TVL at the review snapshot. The result is operating success and distribution depth, not a claim that every pool, launch, LP, or RAY holder is profitable.","confidence":"high","as_of":"2026-07-29","source_refs":["https://docs.raydium.io/introduction/what-is-raydium","https://docs.raydium.io/ray/protocol-fees","https://api.llama.fi/summary/dexs/raydium?dataType=dailyVolume","https://api.llama.fi/protocol/raydium"]},"why":{"summary":"Raydium repeatedly replaced or supplemented its original Serum-linked AMM with products matched to Solana''s changing order flow: standalone CPMM, concentrated liquidity, and LaunchLab. Wallet and aggregator routing gives its pools distribution beyond the Raydium interface, while fee-funded RAY buybacks connect some activity to the token. These mechanisms plausibly explain persistence, but the cited evidence does not isolate their individual causal contribution.","confidence":"medium","source_refs":["https://docs.raydium.io/introduction/what-is-raydium","https://docs.raydium.io/ray/protocol-fees","https://api.llama.fi/summary/dexs/raydium?dataType=dailyVolume"]},"strategic_choices":[{"decision":"Build a Solana-native liquidity stack and distribute it through wallets and aggregators instead of relying only on the first-party interface.","consequence":"Raydium pools receive routed order flow and composability, while depending heavily on Solana activity and third-party routing decisions.","confidence":"high","source_refs":["https://docs.raydium.io/introduction/what-is-raydium"]},{"decision":"Retire the original Serum-linked order-book dependency for current AMM traffic and add CPMM and CLMM products.","consequence":"The protocol survived Serum''s failure and supports more pool designs, but maintains a larger smart-contract and LP-risk surface.","confidence":"high","source_refs":["https://docs.raydium.io/introduction/what-is-raydium"]},{"decision":"Add LaunchLab so bonding-curve launches can graduate directly into Raydium liquidity.","consequence":"Primary issuance becomes a distribution funnel for secondary liquidity, increasing volume opportunity and exposure to speculative launch cycles.","confidence":"high","source_refs":["https://docs.raydium.io/introduction/what-is-raydium"]},{"decision":"Route a disclosed share of swap fees to RAY buybacks.","consequence":"Protocol usage creates observable token demand, though token value capture still depends on fee policy, volume quality, and treasury execution.","confidence":"high","source_refs":["https://docs.raydium.io/ray/protocol-fees"]}],"counterfactual":{"summary":"Keeping the original Serum-linked architecture without standalone pool products would have left Raydium exposed to compromised external upgrade authority after FTX. Avoiding token-launch infrastructure would reduce speculative-cycle risk but surrender an important source of projects, pools, and routed flow. The evidence supports resilience through product adaptation; it cannot prove Raydium would have failed under either alternative.","confidence":"medium","source_refs":["https://docs.raydium.io/introduction/what-is-raydium","https://api.llama.fi/summary/dexs/raydium?dataType=dailyVolume"]},"watch":[{"signal":"Raydium''s Solana DEX share, 30-day volume, TVL, and volume split between recurring pairs and new launches.","implication":"Stable recurring liquidity would support durability; launch-dominated volume would make results more cyclical.","source_refs":["https://api.llama.fi/summary/dexs/raydium?dataType=dailyVolume","https://api.llama.fi/protocol/raydium"]},{"signal":"Fee allocation, realized RAY buybacks, program upgrades, and material pool incidents.","implication":"Consistent buybacks and secure upgrades support token and product credibility; policy reversal or exploit loss would weaken it.","source_refs":["https://docs.raydium.io/ray/protocol-fees","https://docs.raydium.io/introduction/what-is-raydium"]}],"unknowns":["What share of routed Raydium volume is organic recurring flow rather than launch-cycle or incentive-driven activity?","What is aggregate LP performance after inventory loss, out-of-range capital, incentives, and rebalancing cost?","How concentrated are program upgrade authority, treasury control, and aggregator-sourced order flow?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"mid_exchanges","kind":"dex","slug":"dodo-amm","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"middling","summary":"DODO remains a live multichain AMM and routing product built around its Proactive Market Maker design. The cited DefiLlama snapshots reported about $313.7 million of 30-day DEX volume but only about $11.9 million of TVL at review time, far below the adapter''s historical peak. Middling means a functioning differentiated product with meaningful flow but diminished locked-capital scale, not failure or renewed market leadership.","confidence":"high","as_of":"2026-07-29","source_refs":["https://docs.dodoex.io/en/home/what-is-dodo","https://docs-next.dodoex.io/en/product/pmm-algorithm/the-mathematical-principle-of-pmm","https://docs.dodoex.io/en/home/token-economy","https://api.llama.fi/protocol/dodo-amm","https://api.llama.fi/summary/dexs/dodo-amm?dataType=dailyVolume"]},"why":{"summary":"DODO differentiated through PMM pools that use an external reference price and inventory regression instead of relying only on a constant-product curve. It then expanded into routing, private pools, token creation, and multichain deployments. That breadth preserves utility and volume even with low TVL, but increases oracle, integration, governance, and cross-chain complexity. The evidence supports the mechanism and current activity; it does not prove why DODO lost relative liquidity share.","confidence":"medium","source_refs":["https://docs.dodoex.io/en/home/what-is-dodo","https://docs-next.dodoex.io/en/product/pmm-algorithm/the-mathematical-principle-of-pmm","https://api.llama.fi/protocol/dodo-amm"]},"strategic_choices":[{"decision":"Use an oracle-guided Proactive Market Maker that tries to concentrate inventory around an external market price.","consequence":"Pools can offer capital-efficient quotes, while inheriting oracle quality, parameter, inventory, and rebalancing risk.","confidence":"high","source_refs":["https://docs-next.dodoex.io/en/product/pmm-algorithm/the-mathematical-principle-of-pmm"]},{"decision":"Offer public, private, and pegged pool types plus routing and issuance tools.","consequence":"DODO serves more liquidity use cases than one AMM curve, but product breadth raises maintenance and positioning costs.","confidence":"high","source_refs":["https://docs.dodoex.io/en/home/what-is-dodo"]},{"decision":"Deploy DODO and mapped token supply across many EVM chains.","consequence":"The protocol reaches fragmented markets while splitting liquidity and adding bridge, deployment, and governance coordination risk.","confidence":"high","source_refs":["https://docs.dodoex.io/en/home/token-economy"]},{"decision":"Use DODO and vDODO for governance, incentives, and a documented share of platform revenue.","consequence":"The token has governance and fee-linked utility, but its realized value depends on revenue, distributions, emissions, and participation.","confidence":"high","source_refs":["https://docs.dodoex.io/en/home/token-economy"]}],"counterfactual":{"summary":"A simpler single-chain constant-product AMM would reduce oracle and deployment complexity but erase DODO''s primary differentiation. Concentrating on routing without protocol-owned pool designs could reduce maintenance while making the product more dependent on external liquidity. Current volume shows continuing relevance, but no cited evidence identifies which alternative would have produced stronger retention.","confidence":"low","source_refs":["https://docs.dodoex.io/en/home/what-is-dodo","https://docs-next.dodoex.io/en/product/pmm-algorithm/the-mathematical-principle-of-pmm","https://api.llama.fi/summary/dexs/dodo-amm?dataType=dailyVolume"]},"watch":[{"signal":"Volume-to-TVL ratio, retained LP capital, chain-level concentration, and organic fees.","implication":"Durable flow with retained liquidity supports PMM relevance; falling volume and TVL would indicate continued marginalization.","source_refs":["https://api.llama.fi/protocol/dodo-amm","https://api.llama.fi/summary/dexs/dodo-amm?dataType=dailyVolume"]},{"signal":"Current vDODO distributions, DODO emissions, governance participation, and multichain supply reconciliation.","implication":"Transparent net distributions support token value capture; subsidy-dominated activity or fragmented accounting weakens it.","source_refs":["https://docs.dodoex.io/en/home/token-economy"]}],"unknowns":["How much DODO volume is generated by native pools versus the routing layer and external venues?","What is LP performance by PMM pool after oracle, inventory, and incentive effects?","What net protocol revenue reaches vDODO holders after operating costs and token emissions?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"mid_exchanges","kind":"dex","slug":"spookyswap","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"middling","summary":"SpookySwap remains live with V2 and V3 liquidity, BOO staking, farms, a launchpad, and a Sonic-facing interface. The cited DefiLlama snapshots reported about $106,800 of 30-day volume and roughly $453,000 of V2 TVL at review time, a tiny fraction of the adapter''s historical peak. Middling reflects real continuity and migration with weak current scale, not a dead product or a successful return to former Fantom dominance.","confidence":"high","as_of":"2026-07-29","source_refs":["https://spooky.fi/","https://docs.spooky.fi/","https://blog.soniclabs.com/1inch-integrates-sonic-swaps-speed-and-seamless-defi/","https://api.llama.fi/protocol/spookyswap-v2","https://api.llama.fi/summary/dexs/spookyswap-v2?dataType=dailyVolume"]},"why":{"summary":"SpookySwap built early Fantom distribution around a familiar AMM, BOO incentives, farming, and a bridge, then added immutable V3 contracts and followed ecosystem liquidity toward Sonic. The migration preserved brand and product availability, but the chain transition and intense DEX competition did not restore historical scale. Current operation and low activity are observed; attributing the decline specifically among chain migration, incentives, competition, or user demand remains an inference.","confidence":"medium","source_refs":["https://docs.spooky.fi/","https://spooky.fi/","https://blog.soniclabs.com/1inch-integrates-sonic-swaps-speed-and-seamless-defi/","https://api.llama.fi/protocol/spookyswap-v2"]},"strategic_choices":[{"decision":"Anchor the venue in the Fantom ecosystem with BOO farming and fee-sharing through xBOO.","consequence":"The model built local network effects but concentrated demand in one chain''s liquidity and incentive cycle.","confidence":"high","source_refs":["https://spooky.fi/"]},{"decision":"Deploy immutable V3 AMM contracts while retaining a configurable capped protocol-fee path.","consequence":"Immutability reduces unilateral upgrade risk, while limiting emergency intervention and preserving a bounded fee-governance surface.","confidence":"high","source_refs":["https://docs.spooky.fi/"]},{"decision":"Carry the brand and multiple AMM versions into Sonic rather than remain only on legacy Fantom Opera.","consequence":"SpookySwap keeps access to the successor ecosystem, but must migrate users and liquidity while competing with many native and multichain venues.","confidence":"high","source_refs":["https://spooky.fi/","https://blog.soniclabs.com/1inch-integrates-sonic-swaps-speed-and-seamless-defi/"]}],"counterfactual":{"summary":"Remaining exclusively on Fantom Opera would avoid migration friction but tie the product to a declining legacy network. A full token and contract reset on Sonic might simplify positioning while breaking BOO continuity and legacy LP expectations. The current evidence shows continuity with low scale; it cannot prove that either alternative would have recovered former activity.","confidence":"low","source_refs":["https://spooky.fi/","https://blog.soniclabs.com/1inch-integrates-sonic-swaps-speed-and-seamless-defi/","https://api.llama.fi/protocol/spookyswap-v2"]},"watch":[{"signal":"Sonic V2/V3 volume, TVL, unique traders, aggregator routing share, and legacy Fantom liquidity.","implication":"Sustained Sonic growth would support recovery; continued low volume would confirm a live but marginal venue.","source_refs":["https://api.llama.fi/protocol/spookyswap-v2","https://api.llama.fi/summary/dexs/spookyswap-v2?dataType=dailyVolume","https://blog.soniclabs.com/1inch-integrates-sonic-swaps-speed-and-seamless-defi/"]},{"signal":"BOO fee distributions, emissions, migration support, and security incidents across versions.","implication":"Net fee-backed utility and safe migration strengthen the token thesis; subsidy dependence or stranded liquidity weakens it.","source_refs":["https://spooky.fi/","https://docs.spooky.fi/"]}],"unknowns":["How much liquidity and how many active users migrated from Fantom to Sonic?","What portion of BOO staking yield is funded by recurring fees rather than incentives?","How is volume split among SpookySwap versions, chains, the launchpad, and the perpetuals interface?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"dex","slug":"bunni","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Bunni''s operating DEX product is dead after the September 2025 exploit and subsequent wind-down. Its own post-mortem records about $8.4 million taken from Ethereum and Unichain pools, with withdrawals later reopened while deposits and swaps stayed paused. Independent reporting records the team''s October decision to cease operations because a secure relaunch and recovery costs exceeded available resources. Residual withdrawable TVL is not treated as active exchange operation.","confidence":"high","as_of":"2026-07-29","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/","https://www.coindesk.com/business/2025/10/23/bunni-dex-shuts-down-cites-recovery-costs-after-usd8-4m-exploit","https://api.llama.fi/protocol/bunni"]},"why":{"summary":"Bunni added custom liquidity-density logic and idle-balance accounting around concentrated liquidity. The official analysis says a sophisticated transaction sequence exploited rounding behavior during repeated tiny withdrawals and swaps, creating an artificial liquidity change. The team restored withdraw-only access but concluded that secure redesign, audits, and recovery were unaffordable. The exploit mechanism and shutdown are evidenced; the broader claim that product complexity alone caused failure is an inference.","confidence":"high","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/","https://www.coindesk.com/business/2025/10/23/bunni-dex-shuts-down-cites-recovery-costs-after-usd8-4m-exploit"]},"strategic_choices":[{"decision":"Add custom liquidity-density and idle-balance logic to improve concentrated-liquidity deployment.","consequence":"Bunni differentiated its LP product while creating additional accounting states and rounding boundaries that existing tests did not cover.","confidence":"high","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/"]},{"decision":"Deploy across Ethereum and Unichain and allow composition with external flash-liquidity venues.","consequence":"The protocol gained access to multiple liquidity markets, while exploitability differed by available flash liquidity and external composition.","confidence":"high","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/"]},{"decision":"Reopen withdrawals but keep swaps and deposits paused after the exploit.","consequence":"LPs could exit remaining positions without re-exposing pools to the known attack path, but the venue stopped serving its exchange function.","confidence":"high","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/"]},{"decision":"Wind down rather than fund a full redesign, audit program, and relaunch.","consequence":"The team avoided presenting an underfunded restart as safe, while crystallizing the product''s failure and leaving recovery work.","confidence":"high","source_refs":["https://www.coindesk.com/business/2025/10/23/bunni-dex-shuts-down-cites-recovery-costs-after-usd8-4m-exploit"]}],"counterfactual":{"summary":"Invariant tests covering repeated tiny withdrawals, rounding direction, extreme spot movement, and atomic liquidity changes could have exposed the vulnerable state before deployment. Simpler accounting would reduce attack surface but might also remove Bunni''s differentiating capital-allocation behavior. A larger treasury or insurance reserve could fund recovery, but would not itself prove a redesigned protocol safe.","confidence":"high","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/","https://www.coindesk.com/business/2025/10/23/bunni-dex-shuts-down-cites-recovery-costs-after-usd8-4m-exploit"]},"watch":[{"signal":"Recovered assets, remaining LP withdrawals, litigation, and final loss allocation.","implication":"Recovery changes creditor and LP outcomes but does not revive the exchange without a verified relaunch.","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/","https://api.llama.fi/protocol/bunni"]},{"signal":"Any successor deployment, independent audits, invariant suite, funding, and new operating team.","implication":"Only a separately verified operating product could move the classification from dead to recovering.","source_refs":["https://blog.bunni.xyz/posts/exploit-post-mortem/","https://www.coindesk.com/business/2025/10/23/bunni-dex-shuts-down-cites-recovery-costs-after-usd8-4m-exploit"]}],"unknowns":["What final amount will be recovered and distributed to affected LPs?","What treasury, insurance, and legal resources remain for wind-down obligations?","Will any successor reuse Bunni code, brand, or contracts under a funded and independently reviewed team?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"dex","slug":"saddle-finance","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Saddle Finance''s DAO voted in August 2023 to wind down protocol operations and treasury under SIP-54. Contemporary governance records show the proposal passed with 99.78% of recorded voting power, and affected partner governance subsequently designed exit paths for Saddle gauges. The adapter still reports residual TVL, but paused or withdrawable legacy pools are not an operating growth venue.","confidence":"high","as_of":"2026-07-29","source_refs":["https://defillama.com/governance/saddle","https://gov.frax.finance/t/fip-280-implement-saddle-l2d4-gauge-ragequit-function-with-20-fee/2528","https://www.coindesk.com/tech/2023/08/08/venture-backed-saddle-finance-proposes-wind-down-dissolution","https://api.llama.fi/protocol/saddle-finance"]},"why":{"summary":"Saddle entered a crowded stable-swap market with open-source multichain pools, SDL governance, gauges, and substantial venture backing. The governance wind-down proposal cited a long bear market, depleted runway, low activity, and difficulty raising additional capital. The DAO chose an orderly shutdown and treasury distribution rather than continue subsidizing a weak competitive position. Those reasons are proposal evidence; the relative weight of product differentiation, emissions, and market conditions is not independently isolated.","confidence":"medium","source_refs":["https://www.coindesk.com/tech/2023/08/08/venture-backed-saddle-finance-proposes-wind-down-dissolution","https://defillama.com/governance/saddle","https://docs.saddle.finance/saddle-faq"]},"strategic_choices":[{"decision":"Compete in low-slippage stable-asset swaps with an open-source Curve-like design.","consequence":"Saddle addressed a clear use case but entered a market with powerful liquidity network effects and limited room for undifferentiated pools.","confidence":"medium","source_refs":["https://docs.saddle.finance/saddle-faq"]},{"decision":"Use SDL governance, ve-style locking, gauges, and incentives across multiple chains.","consequence":"The system attracted partner liquidity while adding emissions, bridge, gauge, and governance coordination costs.","confidence":"high","source_refs":["https://docs.saddle.finance/saddle-faq","https://docs.saddle.finance/governance"]},{"decision":"Put protocol operations and treasury wind-down to a token-holder vote.","consequence":"The DAO chose a documented exit and distributions instead of an unfunded continuation, while leaving partner pools and gauges to unwind separately.","confidence":"high","source_refs":["https://defillama.com/governance/saddle","https://gov.frax.finance/t/fip-280-implement-saddle-l2d4-gauge-ragequit-function-with-20-fee/2528"]}],"counterfactual":{"summary":"Earlier concentration on a smaller number of defensible pools, lower emissions, and a revenue-linked runway trigger might have reduced burn and simplified the product. A merger or technology transfer could preserve contracts and talent without preserving SDL governance. The cited record does not show that any alternative had committed capital or would overcome incumbent liquidity effects.","confidence":"low","source_refs":["https://www.coindesk.com/tech/2023/08/08/venture-backed-saddle-finance-proposes-wind-down-dissolution","https://docs.saddle.finance/saddle-faq"]},"watch":[{"signal":"Residual TVL, pool pause state, ragequit paths, unclaimed treasury assets, and remaining LP exits.","implication":"These determine wind-down quality and trapped-capital risk, not operating success.","source_refs":["https://api.llama.fi/protocol/saddle-finance","https://gov.frax.finance/t/fip-280-implement-saddle-l2d4-gauge-ragequit-function-with-20-fee/2528"]},{"signal":"Any governance-approved successor, code transfer, or funded operating team.","implication":"A new independently operated venue could merit a separate dossier; dormant legacy contracts do not.","source_refs":["https://defillama.com/governance/saddle","https://docs.saddle.finance/governance"]}],"unknowns":["What final share of treasury assets reached SDL and veSDL stakeholders?","How much residual TVL is freely withdrawable versus operationally stranded in partner gauges?","Did Saddle''s code, contributors, or integrations transfer to a funded successor?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"dex","slug":"serum","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"The original Serum order-book protocol is defunct. After FTX collapsed in November 2022, Solana developers treated Serum''s FTX-held program upgrade key as a security risk and rapidly forked the code into community-controlled OpenBook. Some adapter-reported value remains associated with legacy Serum contracts, but the original governance and product were replaced rather than recovered.","confidence":"high","as_of":"2026-07-29","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022","https://cointelegraph.com/news/serum-exchange-rendered-defunct-following-the-collapse-of-alameda-and-ftx","https://api.llama.fi/protocol/serum"]},"why":{"summary":"Serum supplied a shared central-limit order book that many Solana applications depended on, but the upgrade authority remained controlled by FTX-linked keys. When FTX failed, developers could not verify that the authority was uncompromised. The ecosystem preserved the public code and market structure through OpenBook while abandoning the original trust boundary. Failure came from concentrated control and sponsor dependence, not from proof that onchain order books were intrinsically nonviable.","confidence":"high","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022","https://cointelegraph.com/news/serum-exchange-rendered-defunct-following-the-collapse-of-alameda-and-ftx"]},"strategic_choices":[{"decision":"Build a composable central-limit order book as shared Solana market infrastructure.","consequence":"Serum became deeply integrated and economically useful, but downstream protocols inherited its control and continuity risks.","confidence":"high","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022"]},{"decision":"Leave the program upgrade authority under FTX-linked key control.","consequence":"Development stayed coordinated while the sponsor was trusted; FTX''s collapse converted that authority into an ecosystem-wide compromise risk.","confidence":"high","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022"]},{"decision":"Fork Serum v3 into OpenBook under community control instead of attempting to restore the original authority.","consequence":"Solana applications retained compatible order-book infrastructure while Serum''s brand, token thesis, and original governance became obsolete.","confidence":"high","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022","https://cointelegraph.com/news/serum-exchange-rendered-defunct-following-the-collapse-of-alameda-and-ftx"]}],"counterfactual":{"summary":"A transparent multisig or DAO-controlled upgrade authority independent of FTX could have allowed Serum to continue through sponsor insolvency. Immutable code would remove key compromise risk but also prevent emergency upgrades. The successful rapid fork shows the software was portable; it does not prove the SRM-governed product could preserve trust once its control assumptions failed.","confidence":"high","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022","https://cointelegraph.com/news/serum-exchange-rendered-defunct-following-the-collapse-of-alameda-and-ftx"]},"watch":[{"signal":"Residual Serum balances, active markets, integrator dependencies, and any remaining upgrade authority.","implication":"Residual use may require migration and risk controls but does not revive the original operating organization.","source_refs":["https://api.llama.fi/protocol/serum","https://solana.com/nl/news/monthly-community-update-december-2022"]},{"signal":"OpenBook governance, security, and downstream integration concentration.","implication":"Successor outcomes test whether community control corrected Serum''s control failure; they belong to a separate product lifecycle.","source_refs":["https://solana.com/nl/news/monthly-community-update-december-2022"]}],"unknowns":["How much value remains in legacy Serum contracts and which users or applications can safely migrate it?","Which FTX-linked entities retained SRM, fee, or program-control exposure at collapse?","How completely did downstream protocols remove original Serum dependencies?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"dex","slug":"mirror-protocol","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Mirror Protocol''s synthetic-asset venue is dead. Its historical Terra adapter reached roughly $2.21 billion in TVL and later fell to zero; the cited series ends in 2023. The SEC''s litigation record identifies Terraform Labs as launching Mirror and offering MIR and synthetic mAssets. Mirror did not recover after Terra''s May 2022 collapse, and a surviving public code repository is not evidence of an operating exchange.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.sec.gov/enforcement-litigation/litigation-releases/lr-25262","https://www.sec.gov/files/terraform-labs-pte-ltd-amended-complaint.pdf","https://github.com/mirror-protocol","https://api.llama.fi/protocol/mirror"]},"why":{"summary":"Mirror used TerraUSD-denominated collateral and prices to create synthetic exposure to public equities, with MIR governing incentives and parameters. That connected the venue to Terra''s stablecoin, chain, Terraform stewardship, oracle, collateral, and regulatory risks at once. Terra''s collapse destroyed the settlement and collateral environment, while U.S. enforcement challenged the securities and disclosure model. The dependencies are documented; the exact share of failure attributable to each cannot be isolated.","confidence":"high","source_refs":["https://www.sec.gov/enforcement-litigation/litigation-releases/lr-25262","https://www.sec.gov/files/terraform-labs-pte-ltd-amended-complaint.pdf","https://api.llama.fi/protocol/mirror"]},"strategic_choices":[{"decision":"Offer blockchain-based synthetic exposure to U.S.-listed equities through mAssets.","consequence":"Mirror created a globally accessible differentiated product while taking material securities-law, oracle, market-hours, and tracking-risk exposure.","confidence":"high","source_refs":["https://www.sec.gov/enforcement-litigation/litigation-releases/lr-25262","https://www.sec.gov/files/terraform-labs-pte-ltd-amended-complaint.pdf"]},{"decision":"Build collateral, pricing, settlement, and incentives inside the Terra and UST ecosystem.","consequence":"The design gained tight ecosystem composability but concentrated survival on Terra''s chain and stablecoin maintaining economic credibility.","confidence":"high","source_refs":["https://www.sec.gov/files/terraform-labs-pte-ltd-amended-complaint.pdf","https://api.llama.fi/protocol/mirror"]},{"decision":"Use MIR for governance and liquidity incentives around synthetic markets.","consequence":"The token coordinated markets and emissions, but its demand and governance relevance collapsed with the underlying product.","confidence":"high","source_refs":["https://www.sec.gov/enforcement-litigation/litigation-releases/lr-25262"]}],"counterfactual":{"summary":"Using independently diversified collateral, redundant oracle governance, and a chain-independent settlement layer could reduce Terra-specific failure risk. Restricting assets or obtaining compliant wrappers could reduce legal exposure while sacrificing permissionless global access. These controls address visible dependencies, but no cited evidence proves they would create sufficient liquidity or regulatory acceptance.","confidence":"medium","source_refs":["https://www.sec.gov/files/terraform-labs-pte-ltd-amended-complaint.pdf","https://api.llama.fi/protocol/mirror"]},"watch":[{"signal":"Any remaining Mirror contracts, collateral claims, oracle operation, governance activity, or formal shutdown process.","implication":"Residual technical activity changes recovery mechanics, not the dead product label without a functioning market.","source_refs":["https://github.com/mirror-protocol","https://api.llama.fi/protocol/mirror"]},{"signal":"Final Terraform litigation, bankruptcy distributions, and treatment of MIR and mAsset claims.","implication":"Legal outcomes clarify losses and responsibility but do not restore Mirror''s market mechanism.","source_refs":["https://www.sec.gov/enforcement-litigation/litigation-releases/lr-25262","https://www.sec.gov/files/terraform-labs-pte-ltd-amended-complaint.pdf"]}],"unknowns":["What collateral or claim value, if any, remains recoverable by former Mirror users?","Which contracts and oracles remain technically callable, and who controls them?","How much of Mirror''s historical activity depended on incentives versus durable synthetic-asset demand?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}},{"table":"dead_exchanges","kind":"dex","slug":"uranium-finance","forensic_analysis":{"version":"forensic-analysis-v1","outcome":{"label":"dead","summary":"Uranium Finance shut down after two April 2021 smart-contract attacks. A March 2026 U.S. indictment alleges approximately $1.4 million was extracted in the first attack and $53.3 million across 26 liquidity pools in the second, causing the exchange to close; the defendant is presumed innocent unless convicted. Contemporary incident reporting and technical analysis independently identify the second loss and a constant-product calculation error.","confidence":"high","as_of":"2026-07-29","source_refs":["https://www.justice.gov/usao-sdny/pr/maryland-man-charged-defrauding-crypto-exchange-over-50-million-hacks","https://www.coindesk.com/markets/2021/04/28/binance-chain-defi-exchange-uranium-finance-loses-50m-in-exploit","https://dn.institute/research/cyberattacks/incidents/2021-04-28-uranium-finance/"]},"why":{"summary":"Uranium forked a familiar constant-product AMM and changed fee-related arithmetic during a v2 migration. Technical reporting identifies an inconsistent multiplier in the invariant check that let an attacker withdraw far more than supplied. The critical second exploit followed an earlier attack and occurred shortly before a planned v2.1 migration. A loss larger than the venue''s recoverable liquidity ended operations. The indictment''s attribution is alleged, while the code error and economic failure have independent support.","confidence":"high","source_refs":["https://www.justice.gov/usao-sdny/pr/maryland-man-charged-defrauding-crypto-exchange-over-50-million-hacks","https://www.coindesk.com/markets/2021/04/28/binance-chain-defi-exchange-uranium-finance-loses-50m-in-exploit","https://dn.institute/research/cyberattacks/incidents/2021-04-28-uranium-finance/"]},"strategic_choices":[{"decision":"Fork a constant-product AMM and modify fee and invariant arithmetic for Uranium''s own economics.","consequence":"The team launched quickly with familiar market structure, but a small arithmetic inconsistency crossed a critical asset-conservation boundary.","confidence":"high","source_refs":["https://www.coindesk.com/markets/2021/04/28/binance-chain-defi-exchange-uranium-finance-loses-50m-in-exploit","https://dn.institute/research/cyberattacks/incidents/2021-04-28-uranium-finance/"]},{"decision":"Continue operating and prepare another migration after an earlier April 2021 attack.","consequence":"The venue preserved a chance to repair and continue, but remained exposed when the larger exploit occurred before the planned update.","confidence":"high","source_refs":["https://www.justice.gov/usao-sdny/pr/maryland-man-charged-defrauding-crypto-exchange-over-50-million-hacks","https://www.coindesk.com/markets/2021/04/28/binance-chain-defi-exchange-uranium-finance-loses-50m-in-exploit"]},{"decision":"Operate without a reserve capable of absorbing a loss across most liquidity pools.","consequence":"Once the second exploit removed tens of millions of dollars, the protocol could not recapitalize and shut down.","confidence":"medium","source_refs":["https://www.justice.gov/usao-sdny/pr/maryland-man-charged-defrauding-crypto-exchange-over-50-million-hacks"]}],"counterfactual":{"summary":"Differential testing against the upstream invariant, property tests enforcing asset conservation for every fee parameter, and an independent audit of the changed line could have exposed the defect. Pausing after the first attack until the full migration was verified would reduce exposure at the cost of availability. These are technically plausible controls, not proof that every attack path or attribution would have been prevented.","confidence":"high","source_refs":["https://www.coindesk.com/markets/2021/04/28/binance-chain-defi-exchange-uranium-finance-loses-50m-in-exploit","https://dn.institute/research/cyberattacks/incidents/2021-04-28-uranium-finance/"]},"watch":[{"signal":"Criminal-case disposition, seized-asset forfeiture, victim claims, and any additional recovery.","implication":"Those events change realized victim recovery and attribution; allegations remain allegations until adjudicated.","source_refs":["https://www.justice.gov/usao-sdny/pr/maryland-man-charged-defrauding-crypto-exchange-over-50-million-hacks"]},{"signal":"Residual contracts, claimant coordination, and any separately funded successor.","implication":"Only a verified new operating venue would merit a recovering label; old contracts or token trading do not.","source_refs":["https://www.justice.gov/usao-sdny/pr/maryland-man-charged-defrauding-crypto-exchange-over-50-million-hacks","https://dn.institute/research/cyberattacks/incidents/2021-04-28-uranium-finance/"]}],"unknowns":["What final amount will victims recover from seized assets and other proceedings?","What independent reviews occurred before the vulnerable v2 deployment and planned v2.1 migration?","How were losses distributed across LPs, treasury assets, and token holders?"],"review":{"status":"current","last_reviewed_at":"2026-07-29","next_review_at":"2026-08-05","reviewer":"chaindump-research-desk"}}}]}')
)
INSERT OR REPLACE INTO exchange_wave5_forensic_0052 (target_table, kind, slug, analysis)
SELECT
  json_extract(value, '$.table'),
  json_extract(value, '$.kind'),
  json_extract(value, '$.slug'),
  json_extract(value, '$.forensic_analysis')
FROM wave5_payload, json_each(wave5_payload.document, '$.cases');
-- canonical-payload-end

UPDATE successful_exchanges
SET profile = json_set(
      COALESCE(NULLIF(profile, ''), '{}'),
      '$.forensic_analysis',
      json((
        SELECT analysis
        FROM exchange_wave5_forensic_0052 AS wave
        WHERE wave.target_table = 'successful_exchanges'
          AND wave.kind = successful_exchanges.type
          AND wave.slug = successful_exchanges.slug
      ))
    ),
    updated_at = '2026-07-29'
WHERE EXISTS (
  SELECT 1
  FROM exchange_wave5_forensic_0052 AS wave
  WHERE wave.target_table = 'successful_exchanges'
    AND wave.kind = successful_exchanges.type
    AND wave.slug = successful_exchanges.slug
);

UPDATE mid_exchanges
SET profile = json_set(
      COALESCE(NULLIF(profile, ''), '{}'),
      '$.forensic_analysis',
      json((
        SELECT analysis
        FROM exchange_wave5_forensic_0052 AS wave
        WHERE wave.target_table = 'mid_exchanges'
          AND wave.kind = mid_exchanges.kind
          AND wave.slug = mid_exchanges.slug
      ))
    ),
    updated_at = '2026-07-29'
WHERE EXISTS (
  SELECT 1
  FROM exchange_wave5_forensic_0052 AS wave
  WHERE wave.target_table = 'mid_exchanges'
    AND wave.kind = mid_exchanges.kind
    AND wave.slug = mid_exchanges.slug
);

UPDATE dead_exchanges
SET profile = json_set(
      COALESCE(NULLIF(profile, ''), '{}'),
      '$.forensic_analysis',
      json((
        SELECT analysis
        FROM exchange_wave5_forensic_0052 AS wave
        WHERE wave.target_table = 'dead_exchanges'
          AND wave.kind = dead_exchanges.kind
          AND wave.slug = dead_exchanges.slug
      ))
    ),
    updated_at = '2026-07-29'
WHERE EXISTS (
  SELECT 1
  FROM exchange_wave5_forensic_0052 AS wave
  WHERE wave.target_table = 'dead_exchanges'
    AND wave.kind = dead_exchanges.kind
    AND wave.slug = dead_exchanges.slug
);

DROP TABLE IF EXISTS exchange_wave5_forensic_0052;
